"""Quiet original body and shield movement after connected-effect rejection."""
import json
import numpy as np
from PIL import Image
import produce as p
from prepare import reference,support_reference

IDENTITY=('The same original painted Whitegauge armored adult in the reference images, fixed three-quarter view facing screen right. Enclosed ivory gauge helmet with red marks, brass side fitting and red tassel; charcoal split coat and red lining; ivory shoulder and shin plates, brass knees, black gloves and boots, brass belt weights, rear tank and red hoses. Exactly two human arms and legs. Right near hand holds the middle of the one complete rigid calibrated pole, with ivory tapered head, brass round gauge below the head, black sleeves, ivory bands, brass couplers and pointed brass butt. Left far forearm carries the same small round ivory shield with brass rim and boss. Same original body proportions and equipment materials. ')
PLATE=(' Complete original character and both pole ends visible, fixed body root x480 and boot ground y576. Plain solid magenta backdrop identical to the reference throughout. Only quiet physical movement of this original body, cloth and held equipment between the original poses. ')

def prepare(take,clip,refs,action,seed):
 d=p.SOURCE_DIR/take;d.mkdir(exist_ok=False)
 c=dict(unit_id='unit_brasshollow_whitegauge_datum_lancers',clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=refs,guides=[[62,1]],last=0,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(d/'config.json',c);p.prepare(d,c);p.verify(d,c)

if __name__=='__main__':
 prepare('hit_h3_v2','hit',[reference(14),reference(10)],'One continuous gentle backward lean and return. Both knees gradually bend and the torso and closed helmet lean back, with body weight settling toward the rear boot, until the supplied leaning-body painting at frame62. Both boots remain on the same ground contacts. Right elbow bends slightly while the same hand retains its middle grip on the whole upright pole; left elbow carries the small shield close to the chest. Then both knees gradually straighten and the torso returns smoothly forward to the original balanced upright posture. Coat folds, weights, tassel and hoses follow the body naturally. The pole stays whole and straight and the shield stays on the same forearm. ',2026110441)
 prepare('cast_h3_v2','cast',[reference(14),support_reference()],'One continuous physical left-arm shield lift and lowering. Start in the balanced original ready stance. The left elbow gradually lifts and then straightens, carrying the same small round shield above and to screen right of the closed helmet until the supplied raised-shield painting at frame62. Helmet tilts slightly upward with the left arm. Right hand retains the original upright pole in the same middle grip. Both boots remain planted while torso posture follows the raised left shoulder. Then left elbow bends and lowers the same shield smoothly to the original ready position; helmet and torso settle back to their original posture. Natural coat, belt weights, tassel and hoses follow this small body movement. ',2026110442)
 d=p.SOURCE_DIR/'death_h3_v2';d.mkdir(exist_ok=False)
 action=('One continuous physical lowering and settling of the body onto its side. Begin balanced upright in the original ready painting. Both knees gradually bend beneath the torso, lowering the body onto the knees while the closed helmet leans forward. Then the torso tips onto the original side, and the right hand opens as the complete straight pole tips down onto the same ground in front of the body. Left forearm carries the same round shield down with the torso. At frame62 the body is supported low on its side as in the supplied intermediate painting, with the complete pole lying flat in front and the original right glove resting beside it. Then shoulders and closed helmet settle fully onto the ground, while both original legs, coat, rear tank and hoses settle into the supplied final side-lying painting. Remain completely still in that final grounded original posture for the last second. Exactly the same two original arms and legs, shield and whole pole throughout; coat folds and hanging weights follow the torso naturally. ')
 c=dict(unit_id='unit_brasshollow_whitegauge_datum_lancers',clip='death',canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=2026110443,references=[reference(14),reference(12),reference(13)],guides=[[62,1]],last=2,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(d/'config.json',c);p.prepare(d,c);p.verify(d,c)
 old=p.SOURCE_DIR/'cast_h3_v1';p.write(old/'superseded_preparation.json',dict(status='superseded_before_submission',reason='Replace dense repeated raised-shield controls and effect-related negative language with one quiet physical arm midpoint. No original video or latent was generated for this prepared recipe.'))
 old=p.SOURCE_DIR/'death_h3_v1';p.write(old/'superseded_preparation.json',dict(status='superseded_before_submission',reason='Quiet physical lowering/side settling, one intermediate control and original final grounded pose. Exclude ambiguous white alpha fragments in kneeling guide from new references; original guide pixels remain preserved. No original video or latent was generated for this prepared recipe.'))
 delivery=json.loads((p.SOURCE_DIR/'delivery.json').read_bytes());delivery['takes'][2]='hit_h3_v2';delivery['takes'][4]='cast_h3_v2';delivery['takes'][5]='death_h3_v2';delivery['superseded_unsubmitted_takes']=['cast_h3_v1','death_h3_v1'];p.write(p.SOURCE_DIR/'delivery.json',delivery)
 records=[]
 for folder in sorted(p.SOURCE_DIR.glob('*_h3_v*')):
  for f in sorted(folder.glob('guide_*_rgba.png')):
   a=np.asarray(Image.open(f).convert('RGBA')).astype('int16');solid=a[:,:,3]>=250;v=int((np.minimum(a[:,:,0],a[:,:,2])-a[:,:,1])[solid].max());assert v<=24
   records.append(dict(path=f.relative_to(p.ROOT).as_posix(),sha256=p.sha(f),opaque_magenta_chroma_max=v,opaque_pixels=int(solid.sum())))
 p.write(p.SOURCE_DIR/'foreground_measurement.json',dict(unit_id='unit_brasshollow_whitegauge_datum_lancers',measured_guides=len(records),opaque_magenta_chroma_max=max(r['opaque_magenta_chroma_max'] for r in records),unchanged_protected_band=24,records=records,rule='Positive quiet physical lean and shield-arm motion; one midpoint and matched ready endpoints. Fixed model and matte rules unchanged.'))
 print('QUIET_BODY_SHIELD_RECIPES_PREPARED',len(records),flush=True)
